// شيت دورة دواجن تركيبي بنفس بنية ملف المزرعة (أرقام وهمية، بلا أي بيانات حقيقية) لاختبار المستورد.
const col = (c) => {
  let s = '';
  for (let n = c; n > 0; n = Math.floor((n - 1) / 26)) s = String.fromCharCode(65 + ((n - 1) % 26)) + s;
  return s;
};
export function makeFarmSheet() {
  const cells = {};
  const put = (c, r, v, f) => (cells[`${col(c)}${r}`] = { r, c, v, ...(f ? { f } : {}) });
  put(1, 1, 'البداية');
  put(1, 2, '2025-03-01');
  put(1, 4, 'دفعت');
  [10000, 20000, 5000].forEach((v, i) => put(1, 5 + i, v));
  put(1, 8, 35000, '=SUM(A5:A7)');
  put(1, 9, 'العدد');
  put(1, 10, 1000);
  put(1, 11, 'نسبتي في البداية');
  put(1, 12, 1 / 4, '=1/4');
  put(1, 13, 'نسبة الأسر');
  put(1, 14, 1 / 4, '=1/4');
  // دفعتا تربية: الأولى مع ضيف (نصيبنا النصف) والثانية لنا بالكامل وتشمل مصروفات فترة البشاير (1000)
  put(1, 16, 4000);
  put(1, 17, 2000);
  put(1, 18, 6000, '=SUM(A16:A17)');
  put(1, 20, 3000);
  put(1, 21, 3000, '=SUM(A20:A20)');
  put(4, 21, '2025-04-15');
  put(2, 22, 3000, '=A18/2');
  put(2, 23, 6000, '=B22+A21');
  // كتلتا شهور: الأولى بالرقم (4/2025) والثانية «شهر 6» مكتوبة بسنة خاطئة
  const block = (c, head, year, sales, exps, result, factor) => {
    put(c, 1, head);
    put(c + 1, 1, year);
    put(c + 2, 1, result, `=(Table[[#Totals],[الإجمالي]]-Table[[#Totals],[Column2]])*${factor}`);
    sales.forEach(([n, p], i) => put(c, 4 + i, n) && put(c + 1, 4 + i, p));
    exps.forEach((v, i) => put(c + 1, 18 + i, v));
    put(c + 1, 30, exps.reduce((s, x) => s + x, 0), '=SUBTOTAL(109,Table[Column2])');
  };
  // الكتلة الأولى («البداية») = فترة البشاير
  block(3, 5, 2025, [[100, 90], [3, 120], [1, 15000]], [700, 300], ((100 * 90 + 360 + 15000 - 1000) * 0.5), 0.5);
  block(7, 'شهر 6', 2026, [[120, 95], [1, 800]], [6000], ((120 * 95 + 800 - 6000) * 0.5), 0.5);
  return { sheets: [{ name: 'دورة-تجريبية', cells }] };
}
